import{_ as p,a0 as o,w as d,s as c,ao as l,I as n,a1 as i,A as t,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"Linux 下的 Docker 入門教程 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下的 Docker 入門教程 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下的 Docker 入門教程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下的 Docker 入門教程 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220704 Docker Commands Tutorial - Getting Started With Docker In Linux","title":"Linux 下的 Docker 入門教程","tag":"202207","desc":""},"relativePath":"202207/20220704 Docker Commands Tutorial - Getting Started With Docker In Linux.md","filePath":"[post].md"}'),h={name:"202207/20220704 Docker Commands Tutorial - Getting Started With Docker In Linux.md"};function r(k,s,g,b,u,f){const a=o("Link");return d(),c("div",null,[s[22]||(s[22]=l('<h1 id="linux-下的-docker-入門教程" tabindex="-1">Linux 下的 Docker 入門教程 <a class="header-anchor" href="#linux-下的-docker-入門教程" aria-label="Permalink to “Linux 下的 Docker 入門教程”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202207/21/101143uuwylyrrglzjfwj7.jpg" alt=""></p><blockquote><p>面向初學者的 Docker 基本命令指南。</p></blockquote><p>這篇詳細的 Docker 教程覆蓋了核心的 <strong>Docker 命令</strong>，比如，如何創建新容器、運行容器、刪除容器等。另外，這篇教程也解釋瞭如何從已有的容器構建你自己的 Docker 鏡像，如何移除容器和鏡像。言歸正傳，現在開始 Docker 的基本用法。</p><h3 id="docker-安裝步驟" tabindex="-1">Docker 安裝步驟 <a class="header-anchor" href="#docker-安裝步驟" aria-label="Permalink to “Docker 安裝步驟”">​</a></h3><p>大多數現代 Linux 操作系統都可以安裝 Docker。如果還沒安裝過 Docker，請參考下面的步驟：</p>',6)),n("ul",null,[n("li",null,[i(a,{href:"https://ostechnix.com/install-docker-almalinux-centos-rocky-linux/"},{default:t(()=>[...s[0]||(s[0]=[e("在 AlmaLinux、CentOS、Rocky Linux 上安裝 Docker Engine 和 Docker Compose",-1)])]),_:1})]),n("li",null,[i(a,{href:"https://ostechnix.com/install-docker-ubuntu/"},{default:t(()=>[...s[1]||(s[1]=[e("如何在 Ubuntu 上安裝 Docker 和 Docker Compose",-1)])]),_:1})])]),s[23]||(s[23]=l('<h3 id="什麼是-docker-鏡像和-docker-容器" tabindex="-1">什麼是 Docker 鏡像和 Docker 容器？ <a class="header-anchor" href="#什麼是-docker-鏡像和-docker-容器" aria-label="Permalink to “什麼是 Docker 鏡像和 Docker 容器？”">​</a></h3><p>在開始 Docker 之前，我先説明一下 Docker 鏡像和 Docker 容器是什麼。</p><p>Docker 鏡像是一個描述容器如何運行的的文件，Docker 容器是 Docker 鏡像在運行或被終止時的一個階段。</p><p>容器和主機上的其他文件是隔離的。</p><p>當我們運行一個 Docker 容器的時候，它會使用一個被隔離出來的文件系統，這個文件系統是由一個 Docker 鏡像提供的。Docker 鏡像包含了運行應用程序所需要的一切東西 - 所有的依賴、配置、腳本、二進制文件等等。</p><p>鏡像也包含容器所需要的其他配置項，比如説環境變量、默認運行的命令，以及其他元數據。</p><h3 id="linux-下的-docker-入門" tabindex="-1">Linux 下的 Docker 入門 <a class="header-anchor" href="#linux-下的-docker-入門" aria-label="Permalink to “Linux 下的 Docker 入門”">​</a></h3><p>下面的所有步驟都已在 Ubuntu 22.04、20.04 以及 18.04 LTS 服務器版本中測試通過。後續小節中提供的步驟對於所有 Linux 平台都是通用的。比如，在基於 RHEL 的系統中（比如 AlmaLinux）可以運行相同的命令。</p><h4 id="_1、搜索-docker-鏡像" tabindex="-1">1、搜索 Docker 鏡像 <a class="header-anchor" href="#_1、搜索-docker-鏡像" aria-label="Permalink to “1、搜索 Docker 鏡像”">​</a></h4>',9)),n("p",null,[s[3]||(s[3]=e("我們可以從叫做 ",-1)),i(a,{href:"https://hub.docker.com/"},{default:t(()=>[...s[2]||(s[2]=[e("Docker hub",-1)])]),_:1}),s[4]||(s[4]=e(" 的 Docker 官方庫獲得鏡像，或者我們也可以製作自己的鏡像。",-1))]),s[24]||(s[24]=l(`<p>有些人可能不清楚，Docker hub 是一個線上的中心化倉庫，Docker 用户們在上面構建、測試、然後保存他們的 Docker 鏡像。Docker hub 有數以萬計的 Docker 鏡像，而且這個數字還在每天增長。</p><p>你可以從命令列通過 \`\`docker search\` 命令搜索任意 Docker 鏡像。</p><p>比如要搜索基於 <strong>Alpine</strong> Linux 的 Docker 鏡像，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker search alpine</span></span></code></pre></div><p>輸出結果：</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/Search-Docker-Images.png" alt="Search Docker Images"></p><p>搜索基於 <strong>Ubuntu</strong> 的鏡像，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker search ubuntu</span></span></code></pre></div><p>你還可以搜索其他任意的應用，比如 <strong>Nginx</strong>，像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker search nginx</span></span></code></pre></div><p>Docker hub 有各種各樣的鏡像。你能在 Docker hub 上找到各種已構建好的 Docker 鏡像，比如説操作系統、應用，或者多個應用的合體（比如 LAMP 棧）。</p><p>如果你找的東西不在上面，你還可以構建一個鏡像，然後通過 Docker hub 向其他人開放，或者只是自己用。</p><h4 id="_2、下載-docker-鏡像" tabindex="-1">2、下載 Docker 鏡像 <a class="header-anchor" href="#_2、下載-docker-鏡像" aria-label="Permalink to “2、下載 Docker 鏡像”">​</a></h4><p>從終端運行下面的命令可以下載 Ubuntu OS 的 Docker 鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker pull ubuntu</span></span></code></pre></div><p>上面的這個命令會從 Docker hub 下載最新的 Ubuntu 鏡像。</p><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Using default tag: latest</span></span>
<span class="line"><span>latest: Pulling from library/ubuntu</span></span>
<span class="line"><span>405f018f9d1d: Pull complete</span></span>
<span class="line"><span>Digest: sha256:b6b83d3c331794420340093eb706a6f152d9c1fa51b262d9bf34594887c2c7ac</span></span>
<span class="line"><span>Status: Downloaded newer image for ubuntu:latest</span></span>
<span class="line"><span>docker.io/library/ubuntu:latest</span></span></code></pre></div><p>你也可以用下面的命令下載指定版本的 Ubuntu 鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker pull ubuntu:20.04</span></span></code></pre></div><p>Docker 允許我們下載任何鏡像，並且在那個鏡像上創建容器，這些操作與主機的操作系統無關。</p><p>比如要下載 Alpine 系統的鏡像，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker pull alpine</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/Download-Docker-Images.png" alt="Download Docker Images"></p><h4 id="_3、列出-docker-鏡像" tabindex="-1">3、列出 Docker 鏡像 <a class="header-anchor" href="#_3、列出-docker-鏡像" aria-label="Permalink to “3、列出 Docker 鏡像”">​</a></h4><p>所有已下載的 Docker 鏡像都保存在 <code>/var/lib/docker</code> 路徑下。</p><p>要查看所有已下載的 Docker 鏡像，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker images</span></span></code></pre></div><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>REPOSITORY   TAG       IMAGE ID       CREATED       SIZE</span></span>
<span class="line"><span>ubuntu       latest    27941809078c   3 weeks ago   77.8MB</span></span>
<span class="line"><span>ubuntu       20.04     20fffa419e3a   3 weeks ago   72.8MB</span></span>
<span class="line"><span>alpine       latest    e66264b98777   5 weeks ago   5.52MB</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/List-Docker-Images.png" alt="List Docker Images"></p><p>從上面可以看出來，我已經下載了三個 Docker 鏡像 - Ubuntu latest、Ubuntu 20.04 和 Alpine Linux。</p><p>現在，我們看一下接下來如何從下載的鏡像啓動或者運行容器。</p><h4 id="_4、運行-docker-容器" tabindex="-1">4、運行 Docker 容器 <a class="header-anchor" href="#_4、運行-docker-容器" aria-label="Permalink to “4、運行 Docker 容器”">​</a></h4><p>有兩種方法我們可以啓動一個容器 - 使用 Docker 鏡像的<ruby>標籤<rt>TAG</rt></ruby> 或者 <ruby>鏡像 ID<rt>Image ID</rt></ruby>。</p><p>標籤指的是一個特定的鏡像快照，<ruby>鏡像 ID<rt>Image ID</rt></ruby> 是那個鏡像對應的唯一識別碼。</p><p>可以查看下面這個截圖：</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/Docker-Image-Tag-and-ID.png" alt="Docker Image Tag and ID"></p><p>從上面的解脱可以看到，標籤是 <code>latest</code> 和 <code>20.04</code>。</p><ul><li><code>27941809078c</code> 是 Ubuntu latest 的 Docker 鏡像的鏡像 ID，</li><li><code>20fffa419e3a</code> 是 Ubuntu 20.04 的 Docker 鏡像的鏡像 ID，</li><li>而 <code>e66264b98777</code> 是 Alpine latest 的 Docker 鏡像的鏡像 ID。</li></ul><h5 id="_4-1、使用標籤運行容器" tabindex="-1">4.1、使用標籤運行容器 <a class="header-anchor" href="#_4-1、使用標籤運行容器" aria-label="Permalink to “4.1、使用標籤運行容器”">​</a></h5><p>下載選擇好的 Docker 鏡像後，運行下面的命令來啓動 Docker 容器，並且通過它的標籤進行連接。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -t -i ubuntu:latest /bin/bash</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -it ubuntu:latest /bin/bash</span></span></code></pre></div><p>這裏，</p><ul><li><code>-t</code>：在 Ubuntu 容器內分配一個偽終端。</li><li><code>-i</code>：通過從容器獲取一個標準輸入（STDIN），允許我們創建一個可交互的連接。</li><li><code>ubuntu:latest</code>：標籤為 <code>latest</code> 的 Ubuntu Docker 鏡像。</li><li><code>/bin/bash</code>：新容器的 BASH shell。這個是可選項。如果你不加 shell 的話，會分配默認的 shell 給容器。</li></ul><p>啓動容器後，會自動進入容器的 shell（命令列）：</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/Run-Containers-Using-Tag-1.png" alt="Run Containers Using Tag"></p><p>基於最新 Ubuntu 鏡像的容器現在已經啓動了。所有的新容器都會被賦予一個名字和唯一的 ID。從上面的輸出可以看到，那個 Ubuntu 容器的 ID 是 <code>2f2a5b826762</code>。一會兒我們會看到從哪找到容器的名字。</p><p>現在就可以在容器裏面工作了。當你完成容器內的工作後，你可以回到主機操作系統的終端（在我這個例子中，操作系統是 Ubuntu 22.04 LTS）而不需要關掉容器（客户機）。</p><h5 id="_4-2、從運行中的容器中脱離" tabindex="-1">4.2、從運行中的容器中脱離 <a class="header-anchor" href="#_4-2、從運行中的容器中脱離" aria-label="Permalink to “4.2、從運行中的容器中脱離”">​</a></h5><p>使用 <code>CTRL+P</code> 然後 <code>CTRL+Q</code> 就可以從運行中的容器脱離（不需要關閉）。</p><p>現在，你就回到了你原來的主機的終端窗口。請注意，容器還在後台運行中，我們並沒有關掉它。</p><h5 id="_4-3、使用鏡像-id-運行容器" tabindex="-1">4.3、使用鏡像 ID 運行容器 <a class="header-anchor" href="#_4-3、使用鏡像-id-運行容器" aria-label="Permalink to “4.3、使用鏡像 ID 運行容器”">​</a></h5><p>另一種啓動容器並且連接進去的方式是通過使用鏡像 ID，像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -it 20fffa419e3a /bin/bash</span></span></code></pre></div><p>這裏，</p><ul><li><code>20fffa419e3a</code> - 鏡像 ID</li></ul><p>按 <code>CTRL+P</code> 然後 <code>CTRL+Q</code> 可以從當前容器中脱離回到主機系統的終端。我們只是從容器中脱離，但是沒有讓它停止。容器仍然在後台運行中。</p><h5 id="_4-4-在脱離模式中運行容器" tabindex="-1">4.4. 在脱離模式中運行容器 <a class="header-anchor" href="#_4-4-在脱離模式中運行容器" aria-label="Permalink to “4.4. 在脱離模式中運行容器”">​</a></h5><p>在前面的小結中，我們啓動了一個容器並且立刻連接了進去。然後當容器中的工作結束後，我們從容器中脱離了出來。</p><p>你也可以在脱離模式（不需要自動連接進去）中啓動容器。</p><p>在後台運行一個容器，輸入命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -it -d alpine:latest</span></span></code></pre></div><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>d74f2ceb5f3ad2dbddb0b26e372adb14efff91e75e7763418dbd12d1d227129d</span></span></code></pre></div><p>上面輸出結果的前 12 字符代表的是容器的 ID。</p><p>通過 <code>docker ps</code> 命令，你可以驗證容器是否在運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker ps</span></span>
<span class="line"><span>CONTAINER ID   IMAGE           COMMAND     CREATED         STATUS         PORTS     NAMES</span></span>
<span class="line"><span>d74f2ceb5f3a   alpine:latest   &quot;/bin/sh&quot;   3 seconds ago   Up 2 seconds             zen_pascal</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/Run-Containers-In-Background-1.png" alt="Run Containers In Background"></p><p>從上面個的輸出結果中可以看到，我們創建了一個 Alpine 容器，但是還沒有連接進去。</p><p>如果你想連接進去，很簡單，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker attach d74f2ceb5f3a</span></span></code></pre></div><h4 id="_5、查看運行中的容器" tabindex="-1">5、查看運行中的容器 <a class="header-anchor" href="#_5、查看運行中的容器" aria-label="Permalink to “5、查看運行中的容器”">​</a></h4><p>查看運行中的容器，運行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker ps</span></span></code></pre></div><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CONTAINER ID   IMAGE           COMMAND       CREATED          STATUS          PORTS     NAMES</span></span>
<span class="line"><span>f7e04eed577e   20fffa419e3a    &quot;/bin/bash&quot;   6 minutes ago    Up 6 minutes              brave_mclean</span></span>
<span class="line"><span>2f2a5b826762   ubuntu:latest   &quot;/bin/bash&quot;   18 minutes ago   Up 18 minutes             hungry_leavitt</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/View-Running-Containers.png" alt="View Running Containers"></p><p>這裏，</p><ul><li><code>f7e04eed577e</code> 是由鏡像 <code>2f2a5b826762</code> 創建的 Ubuntu 容器的 ID。並且，<code>brave_mclean</code> 是這個容器的名字。</li><li><code>2f2a5b826762</code> 是由鏡像 “ubuntu：latest” 創建的 Ubuntu 容器的 ID。並且，<code>hungry_leavitt</code> 是這個容器的名字。</li></ul><p>當一個新容器被創建後，會賦給它一個唯一的 ID 和名字，這樣我們就能通過它的 ID 和名字來連接它。</p><p><strong>注意：請注意容器 ID 和 Docker 鏡像 ID 是不同的</strong>。</p><p>列出所有可用的（運行或者停止）容器，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker ps -a</span></span></code></pre></div><h4 id="_6、從運行中的容器脱離或連接" tabindex="-1">6、從運行中的容器脱離或連接 <a class="header-anchor" href="#_6、從運行中的容器脱離或連接" aria-label="Permalink to “6、從運行中的容器脱離或連接”">​</a></h4><p>首先，通過 <code>docker ps</code> 命令找到容器的 ID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker ps</span></span></code></pre></div><p>然後，運行 <code>docker attach</code> 命令連接到運行中的容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker attach &lt;container-id&gt;</span></span></code></pre></div><p>比如像下面這樣，我要連接到 ID 為 <code>f7e04eed577e</code> 的容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker attach f7e04eed577e</span></span></code></pre></div><p>你也可以通過使用它的名字連接到一個容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker attach brave_mclean</span></span></code></pre></div><p>現在你就登錄到這個容器了。</p><p>想要從容器脱離，只要按 <code>CTRL+P</code> 然後 <code>CTRL+Q</code>。</p><h4 id="_7、啓動、重啓、暫停和終止容器" tabindex="-1">7、啓動、重啓、暫停和終止容器 <a class="header-anchor" href="#_7、啓動、重啓、暫停和終止容器" aria-label="Permalink to “7、啓動、重啓、暫停和終止容器”">​</a></h4><p>你可以使用容器的名字或 ID 來啓動，重啓，暫停或者終止一個 Docker 容器。</p><p>首先，通過 <code>docker ps -a</code> 命令找到容器的名字或 ID。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/Find-Container-ID-And-Name.png" alt="Find Container ID And Name"></p><p>現在，通過使用 <code>docker start</code> 命令，加上名字或 ID，你可以啓動一個容器，像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker start modest_cray</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker start 10615254bb45</span></span></code></pre></div><p>用空格隔開，就可以<strong>啓動多個容器</strong>，像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker start 24b5ee8c3d3a 56faac6d20ad d74f2ceb5f3a</span></span></code></pre></div><p>優雅的重啓一個運行中的容器，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker start 10615254bb45</span></span></code></pre></div><p>暫停一個運行中的容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker pause 10615254bb45</span></span></code></pre></div><p>把暫停的容器恢復過來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker unpause 10615254bb45</span></span></code></pre></div><p>直到其它容器都停止前，阻塞一個容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker wait 10615254bb45</span></span></code></pre></div><p>我們可以很容易地通過使用它的名字或 ID 來終止一個容器。如果你已經在容器的 shell 裏了，只需要運行下面的命令就可以非常簡單的終止：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># exit</span></span></code></pre></div><p>你也可以使用下面的命令從 Docker 的主機系統中終止（關閉容器）容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker stop 10615254bb45</span></span></code></pre></div><p>用空格隔開，你可以退出多個容器，像下面這樣。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker stop 35b5ee8c3d3a 10615254bb45</span></span></code></pre></div><p>在退出容器之後，通過列出所有容器的命令來確保它確實被終止了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker ps</span></span></code></pre></div><h4 id="_8、強行關閉-docker-容器" tabindex="-1">8、強行關閉 Docker 容器 <a class="header-anchor" href="#_8、強行關閉-docker-容器" aria-label="Permalink to “8、強行關閉 Docker 容器”">​</a></h4><p><code>docker stop</code> 命令可以非常優雅的關掉運行中的容器。有時候，你可能卡在一個沒有響應的容器，或者你想強制關掉容器。</p><p>通過給一個運行中的容器發送 <code>SIGKILL</code> 來強行關閉容器，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker kill 10615254bb45</span></span></code></pre></div><h4 id="_9、在關閉容器後自動刪除他們" tabindex="-1">9、在關閉容器後自動刪除他們 <a class="header-anchor" href="#_9、在關閉容器後自動刪除他們" aria-label="Permalink to “9、在關閉容器後自動刪除他們”">​</a></h4><p>也許你想測試一個容器，然後當你完成在容器中的工作就把它刪掉。如果是這樣，通過使用 <code>--rm</code> 標籤在關閉後自動刪掉容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -it --rm debian:latest</span></span></code></pre></div><p>當你從容器中退出，它會自動被刪掉。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/Automatically-Delete-Containers.png" alt="Automatically Delete Containers"></p><p>從上面的結果可以看到，我先創建了一個新的 Debian 容器。當我退出這個容器的時候，它就被自動刪掉了。<code>docker ps -a</code> 命令的輸出結果顯示，Debian 容器現在不存在。</p><h4 id="_10、給容器命名" tabindex="-1">10、給容器命名 <a class="header-anchor" href="#_10、給容器命名" aria-label="Permalink to “10、給容器命名”">​</a></h4><p>如果你再看一下之前命令的輸出結果，當你啓動一個容器的時候，每個容器都被賦予了一個隨機的名字。如果你不命名你的容器，Docker 會自動替你給他們命名。</p><p>現在看一下下面的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -it -d alpine:latest</span></span>
<span class="line"><span>2af79e97a825c91bf374b4862b9e7c22fc22acd1598005e8bea3439805ec335d</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -it -d alpine:latest</span></span>
<span class="line"><span>80b53b7e661d33696b65c78267fc3f067b6100799c925910db4721963e3fae0a</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker ps</span></span>
<span class="line"><span>CONTAINER ID   IMAGE           COMMAND     CREATED         STATUS         PORTS     NAMES</span></span>
<span class="line"><span>80b53b7e661d   alpine:latest   &quot;/bin/sh&quot;   3 seconds ago   Up 2 seconds             bold_margulis</span></span>
<span class="line"><span>2af79e97a825   alpine:latest   &quot;/bin/sh&quot;   6 seconds ago   Up 5 seconds             recursing_taussig</span></span></code></pre></div><p>從上面的結果可以看到，儘管我用同一個 Docker 鏡像創建了兩個容器，它們獲得了不同的 ID 和名字。</p><p>如果你想給容器賦一個不變的名字，使用 <code>--name</code> 標籤，像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -it -d --name ostechnix_alpine alpine:latest</span></span></code></pre></div><p>上面的命令會在脱離模式中創建一個叫做 <code>ostechnix_alpine</code> 的新容器。</p><p>我們看一下當前運行的容器列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker ps</span></span></code></pre></div><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CONTAINER ID   IMAGE           COMMAND     CREATED         STATUS         PORTS     NAMES</span></span>
<span class="line"><span>397111fac537   alpine:latest   &quot;/bin/sh&quot;   2 seconds ago   Up 2 seconds             ostechnix_alpine</span></span>
<span class="line"><span>80b53b7e661d   alpine:latest   &quot;/bin/sh&quot;   7 minutes ago   Up 7 minutes             bold_margulis</span></span>
<span class="line"><span>2af79e97a825   alpine:latest   &quot;/bin/sh&quot;   7 minutes ago   Up 7 minutes             recursing_taussig</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/Assign-Name-To-Containers.png" alt="Assign Name To Containers"></p><p>注意到上面輸出結果中的第一個容器的名字了嗎？對了，我們給這個容器分配了一個自定義的名字（也就是 <code>ostechnix_alpine</code>）。</p><p>給容器分配自定義的名字可以給我們帶來其他好處。只要看一下容器的名字，我們就能很容易的確定那個容器裏面安裝了什麼。</p><h4 id="_11、構建自定義-docker-鏡像" tabindex="-1">11、構建自定義 Docker 鏡像 <a class="header-anchor" href="#_11、構建自定義-docker-鏡像" aria-label="Permalink to “11、構建自定義 Docker 鏡像”">​</a></h4><p>Docker 不僅僅是下載和使用已存在的容器。你也可以創建自己的自定義 Docker 鏡像。</p><p>現在我們開始一個 Ubuntu 容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -it ubuntu:latest</span></span></code></pre></div><p>現在，你會進入到容器的 shell。</p><p>然後，在容器中，你可以安裝任何的軟件或者做你想做的事情。</p><p>比如，我們在容器中安裝 Apache Web 服務器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt update</span></span>
<span class="line"><span># apt install apache2</span></span></code></pre></div><p>相似地，在容器中，可以根據自己的需要安裝和測試軟件。</p><p>完成以後，從容器脱離（不要退出）回到主機系統的 shell。不要終止或者關閉容器。使用 <code>CTRL+P</code> 然後 <code>CTRL+Q</code> 從容器中脱離，這樣不會關閉容器。</p><p>在你的 Docker 主機的終端，運行下面的命令來找到容器 ID：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker ps</span></span></code></pre></div><p>最後，創建一個當前運行中的容器的 Docker 鏡像，使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker commit 377e6d77ebb5 ostechnix/ubuntu_apache</span></span></code></pre></div><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sha256:bc5e5f95ca592a3585fda2c5a40ec30c98e292046ef70390a2c3b7863cc6f7c1</span></span></code></pre></div><p>這裏，</p><ul><li><code>377e6d77ebb5</code> – Ubuntu 容器的 ID。</li><li><code>ostechnix</code> – 創建容器的用户的名字。</li><li><code>ubuntu_apache</code> – 用户 <code>ostechnix</code> 創建的 Docker 鏡像的名字。</li></ul><p>現在我們查看一下新的 Docker 鏡像是否被創建了，使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker images</span></span></code></pre></div><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ostechnix/ubuntu_apache</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/Build-Custom-Docker-Images.png" alt="Build Custom Docker Images"></p><p>從上面給的結果中可以看到，從運行中的容器創建的新 Docker 鏡像已經在我們的 Docker 主機系統中了。</p><p>現在你就可以從這個新的 Docker 鏡像創建行容器了，用之前的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -it ostechnix/ubuntu_apache</span></span></code></pre></div><h4 id="_12、移除容器" tabindex="-1">12、移除容器 <a class="header-anchor" href="#_12、移除容器" aria-label="Permalink to “12、移除容器”">​</a></h4><p>當你在 Docker 容器中完成所有開發後，如果你不需要它們了，你可以刪掉它們。</p><p>為此，首先我們需要終止（關閉）運行中的容器。</p><p>用這個命令來看一下運行中的容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker ps</span></span></code></pre></div><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CONTAINER ID   IMAGE           COMMAND   CREATED         STATUS         PORTS     NAMES</span></span>
<span class="line"><span>377e6d77ebb5   ubuntu:latest   &quot;bash&quot;    7 minutes ago   Up 7 minutes             elegant_beaver</span></span></code></pre></div><p>通過使用它的 ID 來終止運行中的容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker stop 377e6d77ebb5</span></span></code></pre></div><p>現在，使用這個命令刪除容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker rm 377e6d77ebb5</span></span></code></pre></div><p>同樣，如果不再需要所有的容器，關閉並刪除它們。</p><p>一個一個的刪除多個容器會是一項繁瑣的工作。所以，我們可以把所有停止的容器一次性刪掉，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker container prune</span></span></code></pre></div><p>敲 <code>Y</code> 然後回車鍵，這些容器就被刪掉了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>WARNING! This will remove all stopped containers.</span></span>
<span class="line"><span>Are you sure you want to continue? [y/N] y</span></span>
<span class="line"><span>Deleted Containers:</span></span>
<span class="line"><span>397111fac5374921b974721ee646b2d5fbae61ca9c6e8b90fbf47952f382a46b</span></span>
<span class="line"><span>80b53b7e661d33696b65c78267fc3f067b6100799c925910db4721963e3fae0a</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>Total reclaimed space: 176B</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/Delete-Containers.png" alt="Delete Containers"></p><p>這個命令只有在最新版中有效。</p><p>使用下面的命令來驗證是否所有容器都被刪除了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker ps -a</span></span></code></pre></div><p>如果看不到任何結果，説明所有容器被刪掉了。</p><h4 id="_13、刪除-docker-鏡像" tabindex="-1">13、刪除 Docker 鏡像 <a class="header-anchor" href="#_13、刪除-docker-鏡像" aria-label="Permalink to “13、刪除 Docker 鏡像”">​</a></h4><p>記住，在刪除所有鏡像之前，首先要刪掉所有從那些鏡像創建的容器。</p><p>當你刪掉容器後，你可以刪掉你不需要的 Docker 鏡像。</p><p>列出所有下載的 Docker 鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker images</span></span></code></pre></div><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>REPOSITORY                TAG       IMAGE ID       CREATED          SIZE</span></span>
<span class="line"><span>ostechnix/ubuntu_apache   latest    bc5e5f95ca59   14 minutes ago   229MB</span></span>
<span class="line"><span>debian                    latest    d2780094a226   11 days ago      124MB</span></span>
<span class="line"><span>ubuntu                    latest    27941809078c   3 weeks ago      77.8MB</span></span>
<span class="line"><span>ubuntu                    20.04     20fffa419e3a   3 weeks ago      72.8MB</span></span>
<span class="line"><span>alpine                    latest    e66264b98777   5 weeks ago      5.52MB</span></span></code></pre></div><p>從上面可以看到，在我們的主機上有 5 個 Docker 鏡像。</p><p>通過使用鏡像 ID 來刪掉它們：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker rmi ce5aa74a48f1</span></span></code></pre></div><p>輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Untagged: ostechnix/ubuntu_apache:latest</span></span>
<span class="line"><span>Deleted: sha256:bc5e5f95ca592a3585fda2c5a40ec30c98e292046ef70390a2c3b7863cc6f7c1</span></span>
<span class="line"><span>Deleted: sha256:a8e4797160a2b2d33d8bd1bd67e008260c022b3a53fbcc198b2b74d9eae5961d</span></span></code></pre></div><p>同樣，刪除其他所有 Docker 鏡像。</p><p>刪掉所有未運行的容器、所有鏡像、構建的緩存、所有網絡，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker system prune -a</span></span></code></pre></div><p>使用這個命令的時候要注意，它會刪掉所有沒有使用的容器、網絡、鏡像（包括 <ruby>掛起<rt>dangling</rt></ruby>和<ruby>未使用<rt>unreferenced</rt></ruby> 的）</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/07/Delete-Everything-In-Docker.png" alt="Delete Everything In Docker"></p><p>默認情況下，即使當前沒有容器在使用<ruby>磁盤卷<rt>volumes</rt></ruby>，為防止重要數據被刪除，磁盤卷也不會被刪除。</p><p>如果你想刪掉所有東西，包括分配的卷，使用 <code>--volumes</code> 標籤。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker system prune -a --volumes</span></span></code></pre></div><h3 id="docker-問題彙總" tabindex="-1">Docker 問題彙總 <a class="header-anchor" href="#docker-問題彙總" aria-label="Permalink to “Docker 問題彙總”">​</a></h3><p>如果 Docker 鏡像正在被運行或停止的容器使用，Docker 不會允許你刪除這些鏡像。</p><p>比如，當我嘗試從一個以前的 Ubuntu 服務器上刪除 ID 為 <code>b72889fa879c</code> 的 Docker 鏡像。我會得到下面的錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Error response from daemon: conflict: unable to delete b72889fa879c (must be forced) - image is being used by stopped container dde4dd285377</span></span></code></pre></div><p>這是因為你想刪除的 Docker 鏡像正在被另一個容器使用。</p><p>所以，我們先查看一下運行中的容器，使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker ps</span></span></code></pre></div><p>輸出結果：</p><p><img src="https://ostechnix.com/wp-content/uploads/2016/04/sk@sk-_005-1-1.jpg" alt="Show running docker containers"></p><p>噢，沒有運行中的容器。</p><p>我們在看一下所有的容器（運行和停止的），用這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker ps -a</span></span></code></pre></div><p>輸出結果：</p><p><img src="https://ostechnix.com/wp-content/uploads/2016/04/sk@sk-_006-1.jpg" alt="Show running and stopped docker containers"></p><p>可以看到，仍然有停止的容器在使用其中一個 Docker 鏡像。所以，我們先把所有容器刪掉。</p><p>比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker rm 12e892156219</span></span></code></pre></div><p>類似地，向上面那樣，用對應容器的 ID 將它們都刪除。</p><p>當把所有容器刪掉後，移除掉 Docker 鏡像。</p><p>比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker rmi b72889fa879c</span></span></code></pre></div><p>就這麼簡單。現在確認是否還有其他 Docker 鏡像在主機上，使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker images</span></span></code></pre></div><p>你現在應該不再有任何 docker 鏡像了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在這篇全面的 Docker 入門教程中，我們解釋了 Docker 的基本操作，比如創建、運行、搜索、刪除容器，還有從 Docker 鏡像構建你自己的容器。同時，我們也解釋瞭如何在不需要 Docker 容器和鏡像的時候刪除它們。</p><p>希望你現在對 <strong>Docker 的使用</strong> 有一個基本的瞭解。</p><p>更多細節，請參考這篇教程最下面的官方資源鏈接，或者在下面的評論區進行評論。</p><h3 id="相關資料" tabindex="-1">相關資料 <a class="header-anchor" href="#相關資料" aria-label="Permalink to “相關資料”">​</a></h3>`,245)),n("ul",null,[n("li",null,[i(a,{href:"https://www.docker.com/"},{default:t(()=>[...s[5]||(s[5]=[e("Docker 官網",-1)])]),_:1})]),n("li",null,[i(a,{href:"https://docs.docker.com/"},{default:t(()=>[...s[6]||(s[6]=[e("Docker 文檔",-1)])]),_:1})])]),s[25]||(s[25]=n("hr",null,null,-1)),n("p",null,[s[8]||(s[8]=e("via: ",-1)),i(a,{href:"https://ostechnix.com/getting-started-with-docker/"},{default:t(()=>[...s[7]||(s[7]=[e("https://ostechnix.com/getting-started-with-docker/",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=e("作者：",-1)),i(a,{href:"https://ostechnix.com/author/sk/"},{default:t(()=>[...s[9]||(s[9]=[e("sk",-1)])]),_:1}),s[14]||(s[14]=e(" 選題：",-1)),i(a,{href:"https://github.com/lkxed"},{default:t(()=>[...s[10]||(s[10]=[e("lkxed",-1)])]),_:1}),s[15]||(s[15]=e(" 譯者：",-1)),i(a,{href:"https://github.com/Yufei-Yan"},{default:t(()=>[...s[11]||(s[11]=[e("MCGA",-1)])]),_:1}),s[16]||(s[16]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[12]||(s[12]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[17]||(s[17]=[e("LCTT",-1)])]),_:1}),s[20]||(s[20]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...s[18]||(s[18]=[e("Linux中國",-1)])]),_:1}),s[21]||(s[21]=e(" 榮譽推出",-1))])])}const C=p(h,[["render",r]]);export{D as __pageData,C as default};
